<script lang="ts">
import * as m from "$lib/paraglide/messages"; import { Button } from "@orbis/ui-svelte/button"; import { Input } from "@orbis/ui-svelte/input"; import { Label } from "@orbis/ui-svelte/label"; import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@orbis/ui-svelte/dialog";
let { open = $bindable(false), name = $bindable(""), onsubmit }: { open: boolean; name: string; onsubmit: () => void } = $props();
</script>
<Dialog bind:open><DialogContent class="max-w-md w-full min-w-0"><DialogHeader><DialogTitle class="text-sm">{m.common_onboarding_add_building_dialog_title()}</DialogTitle></DialogHeader><div class="flex flex-col gap-3 py-2"><div class="flex flex-col gap-1.5"><Label class="text-xs">{m.common_onboarding_add_building_name()}</Label><Input bind:value={name} placeholder={m.common_onboarding_add_building_placeholder()} class="text-xs" autofocus onkeydown={(event: KeyboardEvent) => { if (event.key === "Enter") onsubmit(); }} /></div></div><DialogFooter class="flex items-center justify-end w-full pt-2"><Button variant="outline" size="sm" class="text-xs cursor-pointer" onclick={() => (open = false)}>{m.common_action_cancel()}</Button><Button size="sm" class="text-xs cursor-pointer" onclick={onsubmit} disabled={!name.trim()}>{m.common_onboarding_add_building()}</Button></DialogFooter></DialogContent></Dialog>
